-- Kunci pesan bawaan untuk pegawai aktif yang berhak memakai pesan dan belum membuat kunci (passphrase bawaan: asdasdasd).
-- Dikecualikan: golongan Tenaga Pendukung (id_base 10: supir, satpam, petugas kebersihan) sebanyak 17 akun; mereka tidak memakai pesan.
-- INSERT IGNORE: pengguna yang sudah punya kunci TIDAK diubah. Pengguna yang belum punya akan dibukakan otomatis di browser
-- dan diminta mengganti passphrase (kolom bawaan = 1).
-- Dibuat 2026-11-16 untuk 79 akun. Jalankan setelah chat_messages.sql / chat_messages_e2e.sql.
-- Bila tabel chat_keys sudah ada tanpa kolom bawaan, jalankan dulu sekali:
--   ALTER TABLE `ptpemaco_apam`.`chat_keys` ADD COLUMN `bawaan` TINYINT(1) NOT NULL DEFAULT 0 AFTER `iterasi`;


-- Bila kunci bawaan versi sebelumnya sempat dijalankan untuk semua pegawai, buang yang milik akun yang dikecualikan
-- (hanya kunci bawaan; kunci yang dibuat pengguna sendiri tidak disentuh).
DELETE FROM `ptpemaco_apam`.`chat_keys` WHERE `bawaan` = 1 AND `user_id` IN (33, 41, 60, 67, 77, 109, 110, 112, 143, 161, 162, 163, 164, 165, 166, 167, 202);
